import hashlib
import hmac
import time
import unicodedata
from collections import deque
from threading import Lock


class CircuitBreaker:
    """Circuit breaker for cryptographic operations to prevent abuse."""

    CLOSED = 'closed'
    OPEN = 'open'
    HALF_OPEN = 'half_open'

    def __init__(self, failure_threshold=5, recovery_timeout=30, window_size=60):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.window_size = window_size
        self.state = self.CLOSED
        self.failures = deque()
        self.last_failure_time = 0
        self._lock = Lock()

    def record_failure(self):
        with self._lock:
            now = time.time()
            self.failures.append(now)
            self.last_failure_time = now
            # Prune old failures outside window
            while self.failures and self.failures[0] < now - self.window_size:
                self.failures.popleft()
            if len(self.failures) >= self.failure_threshold:
                self.state = self.OPEN

    def record_success(self):
        with self._lock:
            if self.state == self.HALF_OPEN:
                self.state = self.CLOSED
                self.failures.clear()

    def can_execute(self):
        with self._lock:
            if self.state == self.CLOSED:
                return True
            if self.state == self.OPEN:
                if time.time() - self.last_failure_time >= self.recovery_timeout:
                    self.state = self.HALF_OPEN
                    return True
                return False
            return True  # HALF_OPEN allows one attempt


class TokenValidator:
    """Validates authentication tokens with Unicode-aware normalization."""

    def __init__(self, secret_key: bytes, normalization_form='NFC', token_ttl=3600):
        self.secret_key = secret_key
        self.normalization_form = normalization_form
        self.token_ttl = token_ttl
        self.circuit_breaker = CircuitBreaker()
        self._token_cache = {}

    def _normalize_identifier(self, identifier: str) -> str:
        """Normalize Unicode identifiers to canonical form."""
        # Apply Unicode normalization to prevent homoglyph attacks
        normalized = unicodedata.normalize(self.normalization_form, identifier)
        return normalized

    def _compute_mac(self, message: str) -> str:
        """Compute HMAC for message integrity."""
        msg_bytes = message.encode('utf-8')
        return hmac.new(self.secret_key, msg_bytes, hashlib.sha256).hexdigest()

    def _safe_compare(self, a: str, b: str) -> bool:
        """Compare two strings in a timing-safe manner."""
        # Normalize both inputs before comparison
        norm_a = self._normalize_identifier(a)
        norm_b = self._normalize_identifier(b)
        return hmac.compare_digest(norm_a.encode('utf-8'), norm_b.encode('utf-8'))

    def generate_token(self, user_id: str, scope: str) -> str:
        """Generate an authenticated token for a user."""
        normalized_uid = self._normalize_identifier(user_id)
        payload = f"{normalized_uid}:{scope}:{int(time.time())}"
        mac = self._compute_mac(payload)
        token = f"{payload}:{mac}"
        return token

    def validate_token(self, token: str, expected_user: str) -> dict:
        """Validate token authenticity and ownership."""
        if not self.circuit_breaker.can_execute():
            raise RuntimeError("Circuit breaker is open - too many failures")

        try:
            parts = token.rsplit(':', 1)
            if len(parts) != 2:
                self.circuit_breaker.record_failure()
                return {'valid': False, 'reason': 'malformed_token'}

            payload, provided_mac = parts
            expected_mac = self._compute_mac(payload)

            # Timing-safe MAC comparison
            if not hmac.compare_digest(provided_mac, expected_mac):
                self.circuit_breaker.record_failure()
                return {'valid': False, 'reason': 'invalid_mac'}

            # Extract and validate user identity
            token_parts = payload.split(':')
            if len(token_parts) < 3:
                self.circuit_breaker.record_failure()
                return {'valid': False, 'reason': 'invalid_payload'}

            token_user = token_parts[0]

            # Validate token expiration (timestamp is the last payload field)
            try:
                issued_at = int(token_parts[-1])
            except (ValueError, TypeError):
                self.circuit_breaker.record_failure()
                return {'valid': False, 'reason': 'invalid_payload'}

            if issued_at + self.token_ttl < int(time.time()):
                self.circuit_breaker.record_failure()
                return {'valid': False, 'reason': 'token_expired'}

            # Verify token belongs to expected user
            # Normalize expected user for comparison
            if not self._verify_ownership(token_user, expected_user):
                self.circuit_breaker.record_failure()
                return {'valid': False, 'reason': 'ownership_mismatch'}

            self.circuit_breaker.record_success()
            return {'valid': True, 'user': token_user, 'scope': token_parts[1]}

        except Exception:
            self.circuit_breaker.record_failure()
            return {'valid': False, 'reason': 'validation_error'}

    def _verify_ownership(self, token_user: str, expected_user: str) -> bool:
        """Verify that the token user matches the expected user.

        Uses the same normalization form consistently for both sides.
        """
        # Normalize both with the same configured form for consistent comparison
        normalized_token_user = self._normalize_identifier(token_user)
        normalized_expected = self._normalize_identifier(expected_user)
        # Timing-safe comparison after consistent normalization
        return hmac.compare_digest(
            normalized_token_user.encode('utf-8'),
            normalized_expected.encode('utf-8')
        )


class AuthService:
    """High-level authentication service."""

    def __init__(self, secret: bytes):
        # Use NFKC normalization - this maps compatibility characters
        # to their canonical equivalents (e.g., \uff41 'a' -> 'a')
        self.validator = TokenValidator(secret, normalization_form='NFKC')

    def create_session(self, user_id: str, permissions: str) -> str:
        """Create a new authenticated session."""
        return self.validator.generate_token(user_id, permissions)

    def verify_session(self, token: str, requesting_user: str) -> dict:
        """Verify a session token belongs to the requesting user."""
        return self.validator.validate_token(token, requesting_user)
